'use strict';

window.AUR.shipModule('breakwater/yard', function (use) {
const { TransformNode } = BABYLON;

const { createPetrel } = use('petrel/spacecraft');
const { Fabrication, v, radial } = use('breakwater/fabrication');
const { buildBerth } = use('breakwater/berth');
const { buildRim } = use('breakwater/services');
const { buildHub } = use('breakwater/hub');
const { createFinishes } = use('breakwater/finishes');
const { AXLE_Y, BERTH_RADIUS, BERTHS, CUTTER_SCALE, DECK_Y, GEAR, QUARTER, WHEEL_RADIUS } = use('breakwater/layout');

function addGear(scene,parent,m) {
  const gear=new Fabrication(scene,parent);
  for(const [x,z,mountY] of GEAR) {
    const axle=v(x,AXLE_Y,z);
    gear.tube(m.pipe,v(x,mountY,z-.16),axle,.096,.074);
    gear.tube(m.dark,v(x,mountY,z+.43),axle,.059,.055);
    gear.tube(m.tire,axle.add(v(-.118,0,0)),axle.add(v(.118,0,0)),WHEEL_RADIUS,WHEEL_RADIUS,24);
    for(const s of [-1,1])gear.tube(m.structural,axle.add(v(s*.118,0,0)),axle.add(v(s*.14,0,0)),.12,.10,14);
  }
  gear.finish();
}

function createDrydock(scene) {
  const root=new TransformNode('Breakwater Drydock',scene);
  const finishes=createFinishes(scene);
  const hub=new Fabrication(scene,root);
  buildHub(hub,finishes);
  hub.finish();

  const quarter=new TransformNode('Drydock quadrant',scene);
  quarter.parent=root;
  const frame=new Fabrication(scene,quarter);
  buildBerth(frame,finishes);
  buildRim(frame,finishes);
  frame.finish();

  const cutter=createPetrel(scene).root;
  cutter.parent=root;
  addGear(scene,cutter,finishes);
  const sectors=[quarter],ships=[cutter];
  for(let i=1;i<BERTHS.length;i++){
    sectors.push(quarter.instantiateHierarchy(root));
    ships.push(cutter.instantiateHierarchy(root));
  }
  const height=DECK_Y+CUTTER_SCALE*(WHEEL_RADIUS-AXLE_Y);
  BERTHS.forEach((name,i)=>{
    const heading=i*QUARTER;
    sectors[i].name=name+' quadrant';
    sectors[i].rotation.y=heading;
    ships[i].name='Petrel / '+name;
    ships[i].position.copyFrom(radial(heading,BERTH_RADIUS,height));
    ships[i].rotation.y=heading;
    ships[i].scaling.setAll(CUTTER_SCALE);
  });
  return {root,sectors,ships};
}
return { createDrydock };
});
